// Petshop Rinkinio CTA Banneris kategorijose v1
// Įprastų kategorijų archyvo viršuje rodo kvietimą susidėti savo rinkinį + nuorodą į konstruktorių.
add_action('woocommerce_archive_description', function(){
    if (!function_exists('is_product_category') || !is_product_category()) return;
    $term = get_queried_object();
    if (!$term || empty($term->slug)) return;

    // kategorija → žodis + konstruktorių nuorodos
    $map = array(
        'konservai-sunims' => array('w'=>'konservus', 'links'=>array(array('🎁 Susidėk konservų rinkinį šunims', 34207))),
        'konservai-katems' => array('w'=>'konservus', 'links'=>array(array('🎁 Susidėk konservų rinkinį katėms', 34217))),
        'skanestai-sunims' => array('w'=>'skanėstus', 'links'=>array(array('🎁 Skanėstų rinkinys', 34228), array('🦴 Kramtalų rinkinys', 34232))),
        'skanestai-katems' => array('w'=>'skanėstus', 'links'=>array(array('🎁 Susidėk skanėstų rinkinį katei', 34242))),
    );
    if (!isset($map[$term->slug])) return;
    $cfg = $map[$term->slug];

    $btns = '';
    foreach ($cfg['links'] as $l) {
        if (get_post_status($l[1]) !== 'publish') continue;
        $url = get_permalink($l[1]);
        if (!$url) continue;
        $btns .= '<a href="'.esc_url($url).'" class="psc-cta-btn">'.esc_html($l[0]).'</a>';
    }
    if (!$btns) return;

    echo '<div class="psc-cta-banner">';
    echo   '<div class="psc-cta-text">';
    echo     '<span class="psc-cta-title">Nori sutaupyti? Susidėk savo rinkinį!</span>';
    echo     '<span class="psc-cta-sub">Pasirink mėgstamus '.esc_html($cfg['w']).' į vieną dėžę — daugiau imi, pigiau išeina.</span>';
    echo   '</div>';
    echo   '<div class="psc-cta-btns">'.$btns.'</div>';
    echo '</div>';
    ?>
    <style>
    .psc-cta-banner{
        display:flex; align-items:center; justify-content:space-between; gap:20px; flex-wrap:wrap;
        background:linear-gradient(135deg,#3a6b46,#2f5a3a); color:#fff;
        border-radius:14px; padding:20px 26px; margin:0 0 26px;
        box-shadow:0 4px 16px rgba(47,90,58,.18);
    }
    .psc-cta-text{ display:flex; flex-direction:column; gap:4px; }
    .psc-cta-title{ font-size:20px; font-weight:700; line-height:1.2; }
    .psc-cta-sub{ font-size:14px; opacity:.92; }
    .psc-cta-btns{ display:flex; gap:10px; flex-wrap:wrap; }
    .psc-cta-btn{
        display:inline-block; background:#fff; color:#2f5a3a !important;
        font-weight:700; font-size:14px; text-decoration:none;
        padding:11px 20px; border-radius:9px; white-space:nowrap;
        transition:transform .12s ease, box-shadow .12s ease;
    }
    .psc-cta-btn:hover{ transform:translateY(-2px); box-shadow:0 4px 12px rgba(0,0,0,.18); color:#2f5a3a !important; }
    @media (max-width:600px){
        .psc-cta-banner{ flex-direction:column; align-items:flex-start; text-align:left; }
        .psc-cta-btn{ width:100%; text-align:center; }
        .psc-cta-btns{ width:100%; }
    }
    </style>
    <?php
}, 15);
